void testTaskWithTimeFields() {
    Task task = new Task("Test", "Description");
    task.setDuration(new Duration(60));
    task.setStartTime(LocalDateTime.now());

    int id = manager.addTask(task);
    Task savedTask = manager.getTask(id);

