private final Set<Task> prioritizedTasks = new TreeSet<>(Comparator
        .comparing(Task::getStartTime, Comparator.nullsLast(Comparator.naturalOrder()))
        .thenComparing(Task::getId));

public List<Task> getPrioritizedTasks() {
    return new ArrayList<>(prioritizedTasks);
}
```

5. Проверка пересечений:

```java
private boolean tasksIntersect(Task task1, Task task2) {
    return task1.getStartTime().isBefore(task2.getEndTime()) &&
           task2.getStartTime().isBefore(task1.getEndTime());
}

@Override
public int addTask(Task task) {
    if (task.getStartTime() != null && prioritizedTasks.stream()
            .anyMatch(t -> tasksIntersect(t, task))) {
        throw new IllegalStateException("Task intersects with existing tasks");
    }
    int id = super.addTask(task);
    if (task.getStartTime() != null) {
        prioritizedTasks.add(task);
    }
    return id;
}
```

