В классе FileBackedTaskManager обновим метод fromString():

```java
protected Task fromString(String value) {
    String[] parts = value.split(",");
    int id = Integer.parseInt(parts[0]);
    TaskType type = TaskType.valueOf(parts[1]);
    String name = parts[2];
    ProgressTask status = ProgressTask.valueOf(parts[3]);
    String description = parts[4];
    Duration duration = new Duration(Integer.parseInt(parts[5]));
    LocalDateTime startTime = parts[6].isEmpty() ? null : LocalDateTime.parse(parts[6], DateTimeFormatter.ISO_LOCAL_DATE_TIME);

    Task task;
    switch (type) {
        case TASK:
            task = new Task(name, description, duration, startTime);
            break;
        case EPIC:
            task = new Epic(name, description);
            break;
        case SUBTASK:
            int epicId = Integer.parseInt(parts[7]);
            task = new SubTask(name, description, epicId);
            ((SubTask) task).setDuration(duration);
            ((SubTask) task).setStartTime(startTime);
            break;
        default:
            throw new IllegalArgumentException("Неизвестный тип задачи");
    }

    task.setId(id);
    task.setProgress(status);

    return task;
}
```

